import{_ as t,o as a,c as e,ag as i}from"./chunks/framework.DGzMGr_a.js";const g=JSON.parse('{"title":"SSH 密钥跨平台配置指南：macOS + Windows 双系统实战","description":"","frontmatter":{},"headers":[],"relativePath":"ssh/SSH密钥跨平台配置指南.md","filePath":"ssh/SSH密钥跨平台配置指南.md"}'),n={name:"ssh/SSH密钥跨平台配置指南.md"};function l(o,s,d,h,p,r){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="ssh-密钥跨平台配置指南-macos-windows-双系统实战" tabindex="-1">SSH 密钥跨平台配置指南：macOS + Windows 双系统实战 <a class="header-anchor" href="#ssh-密钥跨平台配置指南-macos-windows-双系统实战" aria-label="Permalink to &quot;SSH 密钥跨平台配置指南：macOS + Windows 双系统实战&quot;">​</a></h1><blockquote><p>从此告别反复输密码，安全高效管理你的云主机</p></blockquote><p>运维开发中，我们每天都要通过 <code>ssh</code> 登录服务器，或是用 <code>scp</code> 传输文件。如果每次都要输入长长的密码，不仅效率低下，还存在密码泄露的风险。</p><p><strong>SSH 密钥认证</strong>是目前最安全、最便捷的解决方案。本文将手把手带你完成 <strong>macOS</strong> 和 <strong>Windows</strong> 双系统下的 SSH 密钥配置，并教你配置 <code>~/.ssh/config</code> 别名，最终实现 <strong><code>ssh 别名</code> 一键免密登录</strong>。</p><hr><h2 id="一、核心原理与准备" tabindex="-1">一、核心原理与准备 <a class="header-anchor" href="#一、核心原理与准备" aria-label="Permalink to &quot;一、核心原理与准备&quot;">​</a></h2><p>SSH 密钥由一对文件组成：</p><ul><li><strong>私钥（Private Key）</strong>：保存在你的本地电脑上，<strong>绝不能泄露</strong>。</li><li><strong>公钥（Public Key）</strong>：放置在云主机的 <code>~/.ssh/authorized_keys</code> 文件中。</li></ul><p><strong>工作流程</strong>：当你连接服务器时，客户端用私钥“签名”，服务器用公钥验证，匹配则直接放行，无需输入密码。</p><blockquote><p>💡 <strong>多设备管理小贴士</strong>：你的 Mac 和 Windows 可以各自生成独立的密钥对。只需将所有公钥都<strong>追加</strong>到服务器的 <code>authorized_keys</code> 中，它们就能和平共处，互不影响。</p></blockquote><hr><h2 id="二、macos-配置篇-主力机" tabindex="-1">二、macOS 配置篇（主力机） <a class="header-anchor" href="#二、macos-配置篇-主力机" aria-label="Permalink to &quot;二、macOS 配置篇（主力机）&quot;">​</a></h2><h3 id="_1-生成专用密钥对" tabindex="-1">1. 生成专用密钥对 <a class="header-anchor" href="#_1-生成专用密钥对" aria-label="Permalink to &quot;1. 生成专用密钥对&quot;">​</a></h3><p>为避免覆盖默认密钥，我们为“航控”服务器生成专用密钥：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_rsa_hangkong</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hangkong-mac&quot;</span></span></code></pre></div><p><strong>执行结果（精简）</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your identification has been saved in /Users/你的用户名/.ssh/id_rsa_hangkong</span></span>
<span class="line"><span>Your public key has been saved in /Users/你的用户名/.ssh/id_rsa_hangkong.pub</span></span></code></pre></div><blockquote><p>✅ 生成成功！公钥文件（<code>.pub</code>）就是需要上传到服务器的内容。</p></blockquote><h3 id="_2-将公钥复制到云主机" tabindex="-1">2. 将公钥复制到云主机 <a class="header-anchor" href="#_2-将公钥复制到云主机" aria-label="Permalink to &quot;2. 将公钥复制到云主机&quot;">​</a></h3><p>使用 <code>ssh-copy-id</code> 命令（macOS 自带）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_rsa_hangkong.pub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2222</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@123.123.123.123</span></span></code></pre></div><ul><li><strong>首次执行</strong>，输入一次密码后，提示：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Number of key(s) added: 1</span></span></code></pre></div><ul><li><strong>再次执行（同一把公钥）</strong>，会智能跳过：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Number of key(s) added: 0</span></span></code></pre></div><blockquote><p>✅ <strong>结论</strong>：<code>ssh-copy-id</code> 是幂等的，多次执行<strong>绝对不会</strong>覆盖已有的其他公钥，非常安全。</p></blockquote><h3 id="_3-配置-ssh-config-实现一键免密" tabindex="-1">3. 配置 <code>~/.ssh/config</code>（实现一键免密） <a class="header-anchor" href="#_3-配置-ssh-config-实现一键免密" aria-label="Permalink to &quot;3. 配置 \`~/.ssh/config\`（实现一键免密）&quot;">​</a></h3><p>编辑本地的 <code>~/.ssh/config</code> 文件（没有则新建），添加以下别名配置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host hangkong</span></span>
<span class="line"><span>    HostName 123.123.123.123</span></span>
<span class="line"><span>    User root</span></span>
<span class="line"><span>    Port 2222</span></span>
<span class="line"><span>    IdentityFile ~/.ssh/id_rsa_hangkong</span></span>
<span class="line"><span>    IdentitiesOnly yes</span></span></code></pre></div><p><strong>配置说明</strong>：</p><ul><li><code>Host hangkong</code>：为你服务器起的简短别名。</li><li><code>IdentitiesOnly yes</code>：强制只使用指定的密钥，避免其他缓存干扰。</li></ul><h3 id="_4-🎉-快捷使用效果展示" tabindex="-1">4. 🎉 快捷使用效果展示 <a class="header-anchor" href="#_4-🎉-快捷使用效果展示" aria-label="Permalink to &quot;4. 🎉 快捷使用效果展示&quot;">​</a></h3><p>配置完成后，所有操作彻底告别冗长参数：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作</th><th style="text-align:left;">命令</th><th style="text-align:left;">效果</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SSH 登录</strong></td><td style="text-align:left;"><code>ssh hangkong</code></td><td style="text-align:left;">直接进入服务器终端，无密码提示</td></tr><tr><td style="text-align:left;"><strong>上传文件</strong></td><td style="text-align:left;"><code>scp ./local.txt hangkong:/root/</code></td><td style="text-align:left;">显示进度条，无密码提示</td></tr><tr><td style="text-align:left;"><strong>下载文件</strong></td><td style="text-align:left;"><code>scp hangkong:/root/remote.txt ./</code></td><td style="text-align:left;">显示进度条，无密码提示</td></tr></tbody></table><hr><h2 id="三、windows-配置篇-备用机-出差机" tabindex="-1">三、Windows 配置篇（备用机/出差机） <a class="header-anchor" href="#三、windows-配置篇-备用机-出差机" aria-label="Permalink to &quot;三、Windows 配置篇（备用机/出差机）&quot;">​</a></h2><p>这里推荐使用 Windows 10/11 <strong>自带的原生 OpenSSH 客户端</strong>（无需额外安装 Git Bash）。</p><h3 id="_1-生成密钥对-在-powershell-中执行" tabindex="-1">1. 生成密钥对（在 PowerShell 中执行） <a class="header-anchor" href="#_1-生成密钥对-在-powershell-中执行" aria-label="Permalink to &quot;1. 生成密钥对（在 PowerShell 中执行）&quot;">​</a></h3><p>注意 Windows 下的路径格式：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keygen </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t rsa </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\Users\\你的用户名\\.ssh\\id_rsa_hangkong </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hangkong-win&quot;</span></span></code></pre></div><p>执行结果同 macOS，显示文件保存路径即成功。</p><h3 id="_2-复制公钥到云主机-手工追加" tabindex="-1">2. 复制公钥到云主机（手工追加） <a class="header-anchor" href="#_2-复制公钥到云主机-手工追加" aria-label="Permalink to &quot;2. 复制公钥到云主机（手工追加）&quot;">​</a></h3><p>Windows 没有 <code>ssh-copy-id</code>，我们使用管道命令手动追加（只需输入一次密码）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type C:\\Users\\你的用户名\\.ssh\\id_rsa_hangkong.pub </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2222</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> root@123.123.123.123 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mkdir -p ~/.ssh &amp;&amp; cat &gt;&gt; ~/.ssh/authorized_keys&quot;</span></span></code></pre></div><blockquote><p>⚠️ <strong>注意</strong>：此命令使用 <code>&gt;&gt;</code> 追加。若重复执行多次，<code>authorized_keys</code> 中会出现重复行。建议只执行一次，或登录服务器执行 <code>sort -u ~/.ssh/authorized_keys -o ~/.ssh/authorized_keys</code> 去重。</p></blockquote><h3 id="_3-设置私钥权限-最关键的一步" tabindex="-1">3. 设置私钥权限（最关键的一步！） <a class="header-anchor" href="#_3-设置私钥权限-最关键的一步" aria-label="Permalink to &quot;3. 设置私钥权限（最关键的一步！）&quot;">​</a></h3><p>Windows 对私钥权限极其严格，必须设置为<strong>仅当前用户可读</strong>，否则 SSH 会拒绝使用。</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">icacls C:\\Users\\你的用户名\\.ssh\\id_rsa_hangkong </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">inheritance:r </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">grant </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%USERNAME%:F&quot;</span></span></code></pre></div><p><strong>成功标志</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已成功处理 1 个文件</span></span></code></pre></div><h3 id="_4-配置-windows-下的-config-文件" tabindex="-1">4. 配置 Windows 下的 <code>config</code> 文件 <a class="header-anchor" href="#_4-配置-windows-下的-config-文件" aria-label="Permalink to &quot;4. 配置 Windows 下的 \`config\` 文件&quot;">​</a></h3><p>在 <code>C:\\Users\\你的用户名\\.ssh\\</code> 目录下，<strong>新建一个名为 <code>config</code> 且无任何后缀的文件</strong>，内容如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host hangkong</span></span>
<span class="line"><span>    HostName 123.123.123.123</span></span>
<span class="line"><span>    User root</span></span>
<span class="line"><span>    Port 2222</span></span>
<span class="line"><span>    IdentityFile C:\\Users\\你的用户名\\.ssh\\id_rsa_hangkong</span></span>
<span class="line"><span>    IdentitiesOnly yes</span></span></code></pre></div><p>配置完成后，在 PowerShell 或 CMD 中，同样可以使用 <code>ssh hangkong</code> 一键登录。</p><hr><h2 id="四、服务器端通用配置-与客户端无关" tabindex="-1">四、服务器端通用配置（与客户端无关） <a class="header-anchor" href="#四、服务器端通用配置-与客户端无关" aria-label="Permalink to &quot;四、服务器端通用配置（与客户端无关）&quot;">​</a></h2><p>如果配置完客户端依然提示输入密码，请登录云主机检查以下两项：</p><h3 id="_1-检查-ssh-服务配置" tabindex="-1">1. 检查 SSH 服务配置 <a class="header-anchor" href="#_1-检查-ssh-服务配置" aria-label="Permalink to &quot;1. 检查 SSH 服务配置&quot;">​</a></h3><p>执行命令，确保关键项未被禁用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;PubkeyAuthentication|PermitRootLogin|AuthorizedKeysFile&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span></span></code></pre></div><p><strong>期望输出</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PubkeyAuthentication yes</span></span>
<span class="line"><span>PermitRootLogin yes</span></span>
<span class="line"><span>AuthorizedKeysFile .ssh/authorized_keys</span></span></code></pre></div><p>若某行显示 <code>no</code> 或被注释（带 <code>#</code>），请用 <code>sudo vi /etc/ssh/sshd_config</code> 修改，然后重启服务：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><h3 id="_2-修复服务器文件权限-第二大杀手" tabindex="-1">2. 修复服务器文件权限（第二大杀手） <a class="header-anchor" href="#_2-修复服务器文件权限-第二大杀手" aria-label="Permalink to &quot;2. 修复服务器文件权限（第二大杀手）&quot;">​</a></h3><p>权限过宽会导致 SSH 直接忽略公钥认证，请务必执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 700</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/authorized_keys</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~</span></span></code></pre></div><p>无报错即为修复成功。</p><hr><h2 id="五、排障速查表-debian-13-专用" tabindex="-1">五、排障速查表（Debian 13 专用） <a class="header-anchor" href="#五、排障速查表-debian-13-专用" aria-label="Permalink to &quot;五、排障速查表（Debian 13 专用）&quot;">​</a></h2><p>如果你的系统是 <strong>Debian 12/13</strong>，传统日志文件 <code>/var/log/auth.log</code> 默认不存在，因为系统改用 <code>systemd-journald</code> 管理日志。</p><blockquote><p>使用 tail 监控传统日志文件，查看认证日志（SSH 登录等） <code>sudo tail -f /var/log/auth.log</code></p></blockquote><h3 id="查看实时认证日志" tabindex="-1">查看实时认证日志 <a class="header-anchor" href="#查看实时认证日志" aria-label="Permalink to &quot;查看实时认证日志&quot;">​</a></h3><p>在云主机上执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><p>然后在本地尝试连接，观察日志输出并对照下表：</p><table tabindex="0"><thead><tr><th style="text-align:left;">服务器日志关键词</th><th style="text-align:left;">含义</th><th style="text-align:left;">解决方案</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Accepted publickey for root</code></td><td style="text-align:left;">✅ <strong>认证成功！</strong></td><td style="text-align:left;">免密已生效，无需操作。</td></tr><tr><td style="text-align:left;"><code>Failed publickey for root</code></td><td style="text-align:left;">❌ 公钥内容不匹配</td><td style="text-align:left;">检查服务器 <code>authorized_keys</code> 是否完整在一行。</td></tr><tr><td style="text-align:left;">只有 <code>Accepted password</code></td><td style="text-align:left;">❌ 未发起公钥认证</td><td style="text-align:left;">检查 <code>sshd_config</code> 确保 <code>PubkeyAuthentication yes</code>。</td></tr><tr><td style="text-align:left;"><code>bad ownership or modes</code></td><td style="text-align:left;">❌ 权限错误</td><td style="text-align:left;">立即执行上面第 4 章的权限修复命令。</td></tr><tr><td style="text-align:left;"><code>Timeout before authentication</code></td><td style="text-align:left;">⏱️ 网络超时</td><td style="text-align:left;">检查云主机防火墙是否放行了该端口。</td></tr></tbody></table><hr><h2 id="六、关键命令执行结果速查表" tabindex="-1">六、关键命令执行结果速查表 <a class="header-anchor" href="#六、关键命令执行结果速查表" aria-label="Permalink to &quot;六、关键命令执行结果速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">操作场景</th><th style="text-align:left;">核心命令</th><th style="text-align:left;">成功标志（终端输出）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>生成密钥</strong></td><td style="text-align:left;"><code>ssh-keygen -t rsa -f ~/.ssh/xxx</code></td><td style="text-align:left;"><code>Your identification has been saved...</code></td></tr><tr><td style="text-align:left;"><strong>复制公钥（Mac）</strong></td><td style="text-align:left;"><code>ssh-copy-id -i xxx.pub user@IP</code></td><td style="text-align:left;"><code>Number of key(s) added: 1</code></td></tr><tr><td style="text-align:left;"><strong>复制公钥（Win）</strong></td><td style="text-align:left;"><code>type xxx.pub | ssh ... &quot;cat &gt;&gt;&quot;</code></td><td style="text-align:left;">无报错，无密码提示即成功</td></tr><tr><td style="text-align:left;"><strong>设置私钥权限（Mac）</strong></td><td style="text-align:left;"><code>chmod 600 ~/.ssh/xxx</code></td><td style="text-align:left;">无输出即为成功</td></tr><tr><td style="text-align:left;"><strong>设置私钥权限（Win）</strong></td><td style="text-align:left;"><code>icacls ... /inheritance:r /grant &quot;%USERNAME%:F&quot;</code></td><td style="text-align:left;"><code>已成功处理 1 个文件</code></td></tr><tr><td style="text-align:left;"><strong>一键登录（别名）</strong></td><td style="text-align:left;"><code>ssh hangkong</code></td><td style="text-align:left;">直接进入服务器命令行</td></tr><tr><td style="text-align:left;"><strong>一键上传（别名）</strong></td><td style="text-align:left;"><code>scp ./file hangkong:/root/</code></td><td style="text-align:left;">显示传输进度条</td></tr><tr><td style="text-align:left;"><strong>一键下载（别名）</strong></td><td style="text-align:left;"><code>scp hangkong:/root/file ./</code></td><td style="text-align:left;">显示传输进度条</td></tr></tbody></table><hr><h2 id="七、总结" tabindex="-1">七、总结 <a class="header-anchor" href="#七、总结" aria-label="Permalink to &quot;七、总结&quot;">​</a></h2><p>配置 SSH 密钥的本质其实就三步：</p><ol><li><strong>本地生成</strong>（公私钥对）；</li><li><strong>公钥上传</strong>（追加到服务器 <code>authorized_keys</code>）；</li><li><strong>配置别名</strong>（编辑 <code>~/.ssh/config</code> 指定私钥路径）。</li></ol><p>跨平台（Mac/Win）只是路径和权限命令写法不同，核心逻辑完全一致。配置成功后，你将彻底告别繁琐的密码输入，管理多台服务器也能游刃有余。</p><p><strong>如果这篇文章帮到了你，欢迎点赞、收藏、转发！</strong> 📌</p><p>（全文完）</p>`,87)])])}const k=t(n,[["render",l]]);export{g as __pageData,k as default};
